<template><view class="page"><view class="title">用户奖品核销记录</view><view v-for="item in prizes" :key="item.lotteryRecordId" class="item" @click="logs(item)"><view><text class="prize">{{ item.prizeTitle }}</text><text class="user">{{ item.studentName || item.userId }} {{ item.studentNo || '' }}</text><text class="code">{{ item.redemptionCode || ('GKZH-' + item.lotteryRecordId) }}</text></view><view class="right"><text :class="item.status==='1'?'done':'wait'">{{ item.status==='1'?'已核销':'待核销' }}</text><text class="time">{{ formatDate(item.redeemTime || item.drawTime) }}</text></view></view><view v-if="!prizes.length" class="empty">暂无中奖记录</view></view></template>
<script>import {getPrizeRecords,getPrizeLogs} from '@/api/staff.js';export default{data:()=>({prizes:[]}),onShow(){getPrizeRecords().then(r=>this.prizes=r.data||[]).catch(e=>uni.showToast({title:e.message,icon:'none'}))},methods:{formatDate(v){if(!v)return '';const d=new Date(v);if(isNaN(d.getTime()))return String(v);const p=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}:${p(d.getSeconds())}`},logs(item){if(item.status==='0')return uni.navigateTo({url:'/pages/staff/redeem?recordId='+item.lotteryRecordId});getPrizeLogs(item.lotteryRecordId).then(r=>uni.showModal({title:'核销操作流水',content:(r.data||[]).map(x=>`${x.action} ${this.formatDate(x.createTime)}`).join('\n')||'暂无流水',showCancel:false})).catch(e=>uni.showToast({title:e.message,icon:'none'}))}}}</script>
<style scoped>.page{min-height:100vh;background:#f4f7fb;padding:28rpx 24rpx}.title{font-size:36rpx;font-weight:700;color:#1a2c4a;margin:10rpx 0 24rpx}.item{background:#fff;border-radius:18rpx;margin-bottom:18rpx;padding:26rpx;display:flex;justify-content:space-between}.prize{display:block;font-size:29rpx;font-weight:700;color:#1a2c4a}.user{display:block;color:#8190a5;font-size:23rpx;margin-top:12rpx}.right{text-align:right}.done,.wait{display:block;font-size:24rpx}.done{color:#27ae60}.wait{color:#f2994a}.time{display:block;color:#9cadc0;font-size:20rpx;margin-top:12rpx}.empty{text-align:center;color:#9cadc0;padding:100rpx 0}</style>
